-- Panindigan Messenger Bot - consolidated PostgreSQL schema (panindigan.sql).
-- Generated from database/postgresql/migrations in filename order.
-- Do not edit this file directly; add a new numbered migration instead.

-- ===== 001_core.sql =====
-- Core identity, groups, preferences and application permissions.
CREATE TABLE IF NOT EXISTS bot_users (
  id BIGSERIAL PRIMARY KEY,
  facebook_id TEXT NOT NULL UNIQUE,
  display_name TEXT,
  locale TEXT NOT NULL DEFAULT 'en-PH',
  is_owner BOOLEAN NOT NULL DEFAULT FALSE,
  is_admin BOOLEAN NOT NULL DEFAULT FALSE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS messenger_groups (
  id BIGSERIAL PRIMARY KEY,
  thread_id TEXT NOT NULL UNIQUE,
  name TEXT,
  is_group BOOLEAN NOT NULL DEFAULT TRUE,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  participant_count INTEGER NOT NULL DEFAULT 0,
  last_seen_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS user_preferences (
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  preference_key TEXT NOT NULL,
  value JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, preference_key)
);

CREATE TABLE IF NOT EXISTS group_preferences (
  group_id BIGINT NOT NULL REFERENCES messenger_groups(id) ON DELETE CASCADE,
  preference_key TEXT NOT NULL,
  value JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (group_id, preference_key)
);

CREATE TABLE IF NOT EXISTS app_permissions (
  id BIGSERIAL PRIMARY KEY,
  subject_type TEXT NOT NULL CHECK (subject_type IN ('user', 'group')),
  subject_id TEXT NOT NULL,
  permission TEXT NOT NULL,
  granted BOOLEAN NOT NULL DEFAULT TRUE,
  granted_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (subject_type, subject_id, permission)
);

CREATE TABLE IF NOT EXISTS application_settings (
  setting_key TEXT PRIMARY KEY,
  value JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_bot_users_role ON bot_users (is_owner, is_admin);
CREATE INDEX IF NOT EXISTS idx_messenger_groups_active ON messenger_groups (is_active, last_seen_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_permissions_subject ON app_permissions (subject_type, subject_id);


-- ===== 002_economy.sql =====
-- Durable coin balances, transactions, reward claims and shop inventory.
CREATE TABLE IF NOT EXISTS coin_accounts (
  user_id BIGINT PRIMARY KEY REFERENCES bot_users(id) ON DELETE CASCADE,
  balance BIGINT NOT NULL DEFAULT 0 CHECK (balance >= 0),
  lifetime_earned BIGINT NOT NULL DEFAULT 0 CHECK (lifetime_earned >= 0),
  lifetime_spent BIGINT NOT NULL DEFAULT 0 CHECK (lifetime_spent >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS coin_transactions (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  amount BIGINT NOT NULL,
  transaction_type TEXT NOT NULL,
  reference_id TEXT,
  description TEXT NOT NULL DEFAULT '',
  idempotency_key TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS reward_claims (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  reward_type TEXT NOT NULL,
  reward_period TEXT NOT NULL,
  amount BIGINT NOT NULL,
  claimed_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  next_eligible_at TIMESTAMPTZ NOT NULL,
  idempotency_key TEXT NOT NULL UNIQUE,
  UNIQUE (user_id, reward_type, reward_period)
);

CREATE TABLE IF NOT EXISTS shop_items (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  description TEXT NOT NULL DEFAULT '',
  price BIGINT NOT NULL CHECK (price > 0),
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS inventory_items (
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  item_id BIGINT NOT NULL REFERENCES shop_items(id) ON DELETE CASCADE,
  quantity BIGINT NOT NULL DEFAULT 0 CHECK (quantity >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (user_id, item_id)
);

CREATE TABLE IF NOT EXISTS economy_audit (
  id BIGSERIAL PRIMARY KEY,
  actor_id TEXT,
  target_id TEXT NOT NULL,
  action TEXT NOT NULL,
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_coin_transactions_user ON coin_transactions (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reward_claims_user ON reward_claims (user_id, reward_type, claimed_at DESC);
CREATE INDEX IF NOT EXISTS idx_economy_audit_target ON economy_audit (target_id, created_at DESC);


-- ===== 003_leveling.sql =====
-- Experience, levels, level rewards and temporary boosts.
CREATE TABLE IF NOT EXISTS user_levels (
  user_id BIGINT PRIMARY KEY REFERENCES bot_users(id) ON DELETE CASCADE,
  xp BIGINT NOT NULL DEFAULT 0 CHECK (xp >= 0),
  total_xp BIGINT NOT NULL DEFAULT 0 CHECK (total_xp >= 0),
  level INTEGER NOT NULL DEFAULT 1 CHECK (level >= 1),
  last_message_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS level_rewards (
  level INTEGER PRIMARY KEY CHECK (level >= 1),
  reward_label TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS xp_boosts (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  multiplier NUMERIC(5, 2) NOT NULL CHECK (multiplier > 0),
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_user_levels_xp ON user_levels (xp DESC);
CREATE INDEX IF NOT EXISTS idx_user_levels_level ON user_levels (level DESC);
CREATE INDEX IF NOT EXISTS idx_xp_boosts_user ON xp_boosts (user_id, expires_at DESC);


-- ===== 004_moderation.sql =====
-- Warnings, reports, moderation actions, mutes, blacklists and word filters.
CREATE TABLE IF NOT EXISTS warnings (
  id BIGSERIAL PRIMARY KEY,
  group_id BIGINT REFERENCES messenger_groups(id) ON DELETE SET NULL,
  user_facebook_id TEXT NOT NULL,
  moderator_facebook_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS reports (
  id BIGSERIAL PRIMARY KEY,
  group_id BIGINT REFERENCES messenger_groups(id) ON DELETE SET NULL,
  reporter_facebook_id TEXT NOT NULL,
  target_facebook_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'reviewing', 'resolved', 'dismissed')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS moderation_actions (
  id BIGSERIAL PRIMARY KEY,
  group_id BIGINT REFERENCES messenger_groups(id) ON DELETE SET NULL,
  action_type TEXT NOT NULL,
  target_facebook_id TEXT NOT NULL,
  actor_facebook_id TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS mutes (
  id BIGSERIAL PRIMARY KEY,
  group_id BIGINT NOT NULL REFERENCES messenger_groups(id) ON DELETE CASCADE,
  user_facebook_id TEXT NOT NULL,
  expires_at TIMESTAMPTZ,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (group_id, user_facebook_id)
);

CREATE TABLE IF NOT EXISTS blacklist (
  id BIGSERIAL PRIMARY KEY,
  scope TEXT NOT NULL CHECK (scope IN ('user', 'group')),
  value TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (scope, value)
);

CREATE TABLE IF NOT EXISTS word_filters (
  id BIGSERIAL PRIMARY KEY,
  group_id BIGINT NOT NULL REFERENCES messenger_groups(id) ON DELETE CASCADE,
  word TEXT NOT NULL,
  action TEXT NOT NULL DEFAULT 'warn' CHECK (action IN ('warn', 'delete', 'mute')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (group_id, word)
);

CREATE INDEX IF NOT EXISTS idx_warnings_user ON warnings (user_facebook_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reports_status ON reports (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_moderation_actions_group ON moderation_actions (group_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_mutes_expiry ON mutes (expires_at) WHERE active = TRUE;
CREATE INDEX IF NOT EXISTS idx_word_filters_group ON word_filters (group_id);


-- ===== 005_ai.sql =====
-- AI usage accounting, quotas, feedback and cancellation requests.
CREATE TABLE IF NOT EXISTS ai_usage (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  command_level TEXT NOT NULL CHECK (command_level IN ('ask1', 'ask2', 'ask3', 'ask4', 'ask5', 'ask6')),
  provider TEXT NOT NULL,
  model TEXT NOT NULL,
  input_tokens INTEGER,
  output_tokens INTEGER,
  usage_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  coin_charge INTEGER NOT NULL DEFAULT 0,
  refund_status TEXT NOT NULL DEFAULT 'none' CHECK (refund_status IN ('none', 'partial', 'full', 'not_applicable')),
  success BOOLEAN NOT NULL,
  failure_reason TEXT,
  duration_ms INTEGER NOT NULL DEFAULT 0,
  idempotency_key TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ai_request_quotas (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  command_level TEXT NOT NULL CHECK (command_level IN ('ask1', 'ask2', 'ask3', 'ask4', 'ask5')),
  period_start TIMESTAMPTZ NOT NULL,
  request_count INTEGER NOT NULL DEFAULT 0 CHECK (request_count >= 0),
  UNIQUE (user_id, command_level, period_start)
);

CREATE TABLE IF NOT EXISTS ai_feedback (
  id BIGSERIAL PRIMARY KEY,
  usage_id BIGINT NOT NULL REFERENCES ai_usage(id) ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  comment TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS ai_cancellations (
  id BIGSERIAL PRIMARY KEY,
  request_key TEXT NOT NULL UNIQUE,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_ai_usage_user ON ai_usage (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ai_usage_level ON ai_usage (command_level, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ai_quota_period ON ai_request_quotas (user_id, command_level, period_start);


-- ===== 006_maintenance.sql =====
-- Persistent global maintenance schedules, notifications and state history.
CREATE TABLE IF NOT EXISTS maintenances (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  description TEXT NOT NULL DEFAULT '',
  starts_at TIMESTAMPTZ NOT NULL,
  ends_at TIMESTAMPTZ NOT NULL,
  timezone_name TEXT NOT NULL,
  expected_duration_ms BIGINT NOT NULL CHECK (expected_duration_ms > 0),
  status TEXT NOT NULL CHECK (status IN ('OFF', 'SCHEDULED', 'ACTIVE', 'COMPLETED', 'CANCELLED')),
  notice_message TEXT NOT NULL DEFAULT '',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  actual_start_at TIMESTAMPTZ,
  actual_end_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  notification_status TEXT NOT NULL DEFAULT 'pending',
  CHECK (ends_at > starts_at)
);

CREATE TABLE IF NOT EXISTS maintenance_notifications (
  id BIGSERIAL PRIMARY KEY,
  maintenance_id TEXT NOT NULL REFERENCES maintenances(id) ON DELETE CASCADE,
  notification_type TEXT NOT NULL,
  lead_time_minutes INTEGER NOT NULL DEFAULT 0,
  thread_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'sent', 'failed')),
  error TEXT,
  sent_at TIMESTAMPTZ,
  idempotency_key TEXT NOT NULL UNIQUE,
  UNIQUE (maintenance_id, notification_type, lead_time_minutes, thread_id)
);

CREATE TABLE IF NOT EXISTS maintenance_history (
  id BIGSERIAL PRIMARY KEY,
  maintenance_id TEXT NOT NULL REFERENCES maintenances(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_maintenance_status ON maintenances (status, starts_at);
CREATE INDEX IF NOT EXISTS idx_maintenance_notifications ON maintenance_notifications (maintenance_id, notification_type);
CREATE INDEX IF NOT EXISTS idx_maintenance_history ON maintenance_history (maintenance_id, created_at DESC);


-- ===== 007_announcements.sql =====
-- Developer announcements and per-group delivery tracking.
CREATE TABLE IF NOT EXISTS announcements (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  announcement_type TEXT NOT NULL CHECK (announcement_type IN ('general', 'maintenance', 'interruption', 'release', 'update', 'security', 'emergency')),
  priority TEXT NOT NULL CHECK (priority IN ('normal', 'important', 'urgent')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  scheduled_for TIMESTAMPTZ,
  status TEXT NOT NULL CHECK (status IN ('draft', 'scheduled', 'delivering', 'completed', 'partially_failed', 'failed', 'cancelled')),
  total_targets INTEGER NOT NULL DEFAULT 0 CHECK (total_targets >= 0),
  successful_deliveries INTEGER NOT NULL DEFAULT 0 CHECK (successful_deliveries >= 0),
  failed_deliveries INTEGER NOT NULL DEFAULT 0 CHECK (failed_deliveries >= 0),
  confirmed_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS announcement_deliveries (
  id BIGSERIAL PRIMARY KEY,
  announcement_id TEXT NOT NULL REFERENCES announcements(id) ON DELETE CASCADE,
  thread_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'sent', 'failed', 'skipped')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  error TEXT,
  sent_at TIMESTAMPTZ,
  idempotency_key TEXT NOT NULL UNIQUE,
  UNIQUE (announcement_id, thread_id)
);

CREATE INDEX IF NOT EXISTS idx_announcements_status ON announcements (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_announcement_deliveries ON announcement_deliveries (announcement_id, status);


-- ===== 008_automation.sql =====
-- Per-group automation configuration and response rules.
CREATE TABLE IF NOT EXISTS group_settings (
  thread_id TEXT PRIMARY KEY,
  welcome_message TEXT NOT NULL DEFAULT '',
  goodbye_message TEXT NOT NULL DEFAULT '',
  auto_react_emoji TEXT NOT NULL DEFAULT '',
  auto_delete_seconds INTEGER NOT NULL DEFAULT 0 CHECK (auto_delete_seconds >= 0),
  announcement_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS auto_responses (
  id BIGSERIAL PRIMARY KEY,
  thread_id TEXT NOT NULL,
  trigger_text TEXT NOT NULL,
  response_text TEXT NOT NULL,
  match_mode TEXT NOT NULL DEFAULT 'exact' CHECK (match_mode IN ('exact', 'contains', 'prefix')),
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (thread_id, trigger_text)
);

CREATE TABLE IF NOT EXISTS keyword_triggers (
  id BIGSERIAL PRIMARY KEY,
  thread_id TEXT NOT NULL,
  keyword TEXT NOT NULL,
  response_text TEXT NOT NULL,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (thread_id, keyword)
);

CREATE TABLE IF NOT EXISTS automation_runs (
  id BIGSERIAL PRIMARY KEY,
  thread_id TEXT NOT NULL,
  kind TEXT NOT NULL,
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_auto_responses_thread ON auto_responses (thread_id, active);
CREATE INDEX IF NOT EXISTS idx_keyword_triggers_thread ON keyword_triggers (thread_id, active);
CREATE INDEX IF NOT EXISTS idx_automation_runs_thread ON automation_runs (thread_id, created_at DESC);


-- ===== 009_scheduler.sql =====
-- Durable schedules restored after restarts and their execution history.
CREATE TABLE IF NOT EXISTS scheduled_jobs (
  id TEXT PRIMARY KEY,
  job_kind TEXT NOT NULL,
  payload JSONB NOT NULL,
  due_at TIMESTAMPTZ NOT NULL,
  timezone_name TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'succeeded', 'failed', 'cancelled')),
  attempts INTEGER NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  maximum_attempts INTEGER NOT NULL DEFAULT 5 CHECK (maximum_attempts > 0),
  next_attempt_at TIMESTAMPTZ,
  locked_by TEXT,
  locked_until TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS job_runs (
  id BIGSERIAL PRIMARY KEY,
  job_id TEXT NOT NULL REFERENCES scheduled_jobs(id) ON DELETE CASCADE,
  attempt INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('started', 'succeeded', 'failed')),
  error TEXT,
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  finished_at TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS idx_scheduled_jobs_due ON scheduled_jobs (status, due_at);
CREATE INDEX IF NOT EXISTS idx_scheduled_jobs_lock ON scheduled_jobs (locked_until) WHERE locked_until IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_job_runs_job ON job_runs (job_id, attempt DESC);


-- ===== 010_audit.sql =====
-- Security and operational audit trail shared by privileged commands.
CREATE TABLE IF NOT EXISTS audit_logs (
  id BIGSERIAL PRIMARY KEY,
  actor_facebook_id TEXT,
  action TEXT NOT NULL,
  target_type TEXT NOT NULL,
  target_id TEXT NOT NULL,
  details JSONB NOT NULL DEFAULT '{}'::jsonb,
  severity TEXT NOT NULL DEFAULT 'info' CHECK (severity IN ('info', 'warning', 'critical')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_audit_logs_actor ON audit_logs (actor_facebook_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_logs_action ON audit_logs (action, created_at DESC);


-- ===== 011_bank.sql =====
-- Bank balances are separate from the spendable wallet but remain in PostgreSQL.
CREATE TABLE IF NOT EXISTS bank_accounts (
  user_id BIGINT PRIMARY KEY REFERENCES bot_users(id) ON DELETE CASCADE,
  balance BIGINT NOT NULL DEFAULT 0 CHECK (balance >= 0),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS bank_transactions (
  id BIGSERIAL PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES bot_users(id) ON DELETE CASCADE,
  direction TEXT NOT NULL CHECK (direction IN ('deposit', 'withdraw')),
  amount BIGINT NOT NULL CHECK (amount > 0),
  idempotency_key TEXT NOT NULL UNIQUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_bank_transactions_user ON bank_transactions (user_id, created_at DESC);

